<?php
declare(strict_types=1); require_once __DIR__ . '/includes/bootstrap.php'; require_once __DIR__ . '/config/app.php'; $order=null;$items=[];$error=null;$newOrder=$_SESSION['new_order']??null;unset($_SESSION['new_order']);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$number=strtoupper(trim((string)($_POST['order_number']??'')));$phone=trim((string)($_POST['phone']??''));if($number!==''&&valid_phone($phone)){$statement=db()->prepare('SELECT * FROM orders WHERE order_number=? AND phone=?');$statement->bind_param('ss',$number,$phone);$statement->execute();$order=$statement->get_result()->fetch_assoc();if($order){$_SESSION['tracked_orders'][$order['order_number']]=time();$statement=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$statement->bind_param('i',$order['id']);$statement->execute();$items=$statement->get_result()->fetch_all(MYSQLI_ASSOC);}else $error='No matching order was found.';}else $error='Enter a valid order number and phone number.';}echo '<style>.topbar.wrap .brand>span{display:none!important}.topbar.wrap .brand:before{content:""!important;display:inline-block!important;width:42px!important;height:42px!important;margin-right:10px!important;border-radius:50%!important;background:#07182e url("assets/images/sammy-tech-logo.jpeg") center/cover no-repeat!important;box-shadow:0 0 0 2px #0ea5e9!important;flex:none!important}</style>';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track order | Sammy Tech</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="topbar wrap"><a class="brand" href="index.php"><span>ST</span> SAMMY TECH</a><a class="text-link" href="index.php">← Storefront</a></header><main class="wrap simple-page"><p class="eyebrow">Order tracking</p><h1>Where is my order?</h1><?php if($newOrder):?><p class="flash success">Order <?=e($newOrder)?> received. Enter this number and your phone to track it.</p><?php endif;?><form class="track-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Order number<input name="order_number" required placeholder="ST-..."></label><label>Phone number<input name="phone" required></label><button class="button button-dark">Track order</button></form><?php if($error):?><p class="flash error"><?=e($error)?></p><?php endif;?><?php if($order):?><section class="track-result"><div><p class="eyebrow">Order <?=e($order['order_number'])?></p><h2><?=e(ucfirst($order['status']))?></h2><p><?=e($order['delivery_method']==='delivery'?'Delivery to '.$order['delivery_area'].' · '.$order['delivery_address']:'Collection from Sammy Tech, Juba')?></p></div><div><span class="status status-<?=e($order['payment_status'])?>">Payment <?=e($order['payment_status'])?></span><h3><?=money((float)$order['total_amount'])?></h3><a class="button button-dark" href="receipt.php?order=<?=urlencode($order['order_number'])?>">Print receipt</a></div><ul><?php foreach($items as $item):?><li><?=e((string)$item['quantity'])?> × <?=e($item['product_name'])?> <b><?=money((float)$item['unit_price']*$item['quantity'])?></b></li><?php endforeach;?></ul></section><?php endif;?></main></body></html>
